INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000102,'quizzes','{"id":760200000000102,"title":"A2 · Бизнес · Работа и команда · Quiz 2","description":"A2: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «sales figures».","options":["обслуживание клиентов","отправить электронное письмо","показатели продаж","уложиться в срок"],"correctAnswer":"показатели продаж","explanation":"«sales figures» — «показатели продаж»."},{"id":2,"question":"Какое выражение на британском английском соответствует «собеседование»?","options":["send an email","job interview","sales figures","join a meeting"],"correctAnswer":"job interview","explanation":"«job interview» — «собеседование»."},{"id":3,"question":"Выбери точное русское значение выражения «work schedule».","options":["рабочее расписание","обслуживание клиентов","проверить цену","показатели продаж"],"correctAnswer":"рабочее расписание","explanation":"«work schedule» — «рабочее расписание»."},{"id":4,"question":"Выбери точное русское значение выражения «ask for feedback».","options":["присоединиться к встрече","сделать заказ","отправить электронное письмо","попросить отзыв"],"correctAnswer":"попросить отзыв","explanation":"«ask for feedback» — «попросить отзыв»."},{"id":5,"question":"Какое выражение на британском английском соответствует «совершить платёж»?","options":["sales figures","make a payment","monthly report","ask for feedback"],"correctAnswer":"make a payment","explanation":"«make a payment» — «совершить платёж»."},{"id":6,"question":"Выбери точное русское значение выражения «meet a deadline».","options":["проверить цену","отправить электронное письмо","уложиться в срок","рабочее расписание"],"correctAnswer"