INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000104,'quizzes','{"id":760200000000104,"title":"B2 · Бизнес · Работа и команда · Quiz 4","description":"B2: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «allocate resources».","options":["устранить узкое место","распределить ресурсы","предложить компромисс","прогнозировать спрос"],"correctAnswer":"распределить ресурсы","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":2,"question":"Какое выражение на британском английском соответствует «укрепить лояльность клиентов»?","options":["negotiate terms","manage expectations","address a bottleneck","strengthen customer loyalty"],"correctAnswer":"strengthen customer loyalty","explanation":"«strengthen customer loyalty» — «укрепить лояльность клиентов»."},{"id":3,"question":"Выбери точное русское значение выражения «assess commercial risk».","options":["устранить узкое место","оценить коммерческий риск","оценить результаты работы","укрепить лояльность клиентов"],"correctAnswer":"оценить коммерческий риск","explanation":"«assess commercial risk» — «оценить коммерческий риск»."},{"id":4,"question":"Выбери точное русское значение выражения «review performance».","options":["согласовать условия","оценить коммерческий риск","предложить компромисс","оценить результаты работы"],"correctAnswer":"оценить результаты работы","explanation":"«review performance» — «оценить результаты работы»."},{"id":5,"question":"Какое выражение на британском английском соответствует «обосновать вложение»?","options":["justify an investment","conduct market research","improve the workflow","assess commercial risk"],"correctAnswer":"justify an investment","explanation":"«justify an investment» — «обосновать вложение»."},{"id":6,"question":"Выбери точное русское значение выражения «propose a compromise».","options":["согласовать условия","распределить ресурсы","улучшить рабочий процесс","предложить компромисс"],"correctAnswer":"предложить компромисс","explanation":"«propose a compromise» — «предложить компромисс»."},{"id":7,"question":"Выбери точное русское значение выражения «negotiate terms».","options":["управлять ожиданиями","укрепить лояльность клиентов","согласовать условия","оценить результаты работы"],"correctAnswer":"согласовать условия","explanation":"«negotiate terms» — «согласовать условия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «провести исследование рынка»?","options":["conduct market research","strengthen customer loyalty","address a bottleneck","forecast demand"],"correctAnswer":"conduct market research","explanation":"«conduct market research» — «провести исследование рынка»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000105,'quizzes','{"id":760200000000105,"title":"C1 · Бизнес · Работа и команда · Quiz 5","description":"C1: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «identify structural inefficiencies».","options":["определить измеримые результаты","выявить системные неэффективности","соблюдать профессиональную осмотрительность","оценить долгосрочную жизнеспособность"],"correctAnswer":"выявить системные неэффективности","explanation":"«identify structural inefficiencies» — «выявить системные неэффективности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «интерпретировать финансовые показатели»?","options":["interpret financial indicators","revise the implementation plan","identify structural inefficiencies","establish measurable outcomes"],"correctAnswer":"interpret financial indicators","explanation":"«interpret financial indicators» — «интерпретировать финансовые показатели»."},{"id":3,"question":"Выбери точное русское значение выражения «substantiate a recommendation».","options":["пересмотреть план внедрения","соблюдать профессиональную осмотрительность","обосновать рекомендацию","согласовать стратегические цели"],"correctAnswer":"обосновать рекомендацию","explanation":"«substantiate a recommendation» — «обосновать рекомендацию»."},{"id":4,"question":"Выбери точное русское значение выражения «evaluate a trade-off».","options":["оценить компромисс между целями","пересмотреть план внедрения","соблюдать профессиональную осмотрительность","обосновать рекомендацию"],"correctAnswer":"оценить компромисс между целями","explanation":"«evaluate a trade-off» — «оценить компромисс между целями»."},{"id":5,"question":"Какое выражение на британском английском соответствует «договориться о приемлемом решении»?","options":["mitigate operational risk","negotiate a workable settlement","interpret financial indicators","revise the implementation plan"],"correctAnswer":"negotiate a workable settlement","explanation":"«negotiate a workable settlement» — «договориться о приемлемом решении»."},{"id":6,"question":"Выбери точное русское значение выражения «assess long-term viability».","options":["оценить долгосрочную жизнеспособность","интерпретировать финансовые показатели","соблюдать профессиональную осмотрительность","пересмотреть план внедрения"],"correctAnswer":"оценить долгосрочную жизнеспособность","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":7,"question":"Выбери точное русское значение выражения «manage stakeholder expectations».","options":["пересмотреть план внедрения","оценить компромисс между целями","управлять ожиданиями заинтересованных сторон","снизить операционный риск"],"correctAnswer":"управлять ожиданиями заинтересованных сторон","explanation":"«manage stakeholder expectations» — «управлять ожиданиями заинтересованных сторон»."},{"id":8,"question":"Какое выражение на британском английском соответствует «определить измеримые результаты»?","options":["establish measurable outcomes","substantiate a recommendation","interpret financial indicators","mitigate operational risk"],"correctAnswer":"establish measurable outcomes","explanation":"«establish measurable outcomes» — «определить измеримые результаты»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
