INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000109,'quizzes','{"id":760200000000109,"title":"B1 · Бизнес · Деловая переписка · Quiz 9","description":"B1: деловая переписка. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Деловая переписка","track":"Бизнес","topic":"Деловая переписка","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «increase efficiency».","options":["обсудить предложение","уточнить по электронной почте","повысить эффективность","пересмотреть бюджет"],"correctAnswer":"повысить эффективность","explanation":"«increase efficiency» — «повысить эффективность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «пересмотреть бюджет»?","options":["review the budget","set priorities","follow up by email","request clarification"],"correctAnswer":"review the budget","explanation":"«review the budget» — «пересмотреть бюджет»."},{"id":3,"question":"Выбери точное русское значение выражения «discuss a proposal».","options":["обсудить предложение","учесть расходы","согласовать срок","рассмотреть жалобу"],"correctAnswer":"обсудить предложение","explanation":"«discuss a proposal» — «обсудить предложение»."},{"id":4,"question":"Выбери точное русское значение выражения «handle a complaint».","options":["повысить эффективность","расставить приоритеты","обсудить предложение","рассмотреть жалобу"],"correctAnswer":"рассмотреть жалобу","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":5,"question":"Какое выражение на британском английском соответствует «организовать семинар»?","options":["organise a workshop","follow up by email","set priorities","review the budget"],"correctAnswer":"organise a workshop","explanation":"«organise a workshop» — «организовать семинар»."},{"id":6,"question":"Выбери точное русское значение выражения «follow up by email».","options":["уточнить по электронной почте","рассмотреть жалобу","учесть расходы","организовать семинар"],"correctAnswer":"уточнить по электронной почте","explanation":"«follow up by email» — «уточнить по электронной почте»."},{"id":7,"question":"Выбери точное русское значение выражения «agree on a deadline».","options":["делегировать задачу","согласовать срок","повысить эффективность","подготовить счёт"],"correctAnswer":"согласовать срок","explanation":"«agree on a deadline» — «согласовать срок»."},{"id":8,"question":"Какое выражение на британском английском соответствует «запросить уточнение»?","options":["set priorities","discuss a proposal","request clarification","consider the costs"],"correctAnswer":"request clarification","explanation":"«request clarification» — «запросить уточнение»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000110,'quizzes','{"id":760200000000110,"title":"B2 · Бизнес · Деловая переписка · Quiz 10","description":"B2: деловая переписка. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Деловая переписка","track":"Бизнес","topic":"Деловая переписка","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «assess commercial risk».","options":["оценить коммерческий риск","укрепить лояльность клиентов","предложить компромисс","распределить ресурсы"],"correctAnswer":"оценить коммерческий риск","explanation":"«assess commercial risk» — «оценить коммерческий риск»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оценить результаты работы»?","options":["justify an investment","propose a compromise","review performance","manage expectations"],"correctAnswer":"review performance","explanation":"«review performance» — «оценить результаты работы»."},{"id":3,"question":"Выбери точное русское значение выражения «manage expectations».","options":["согласовать условия","обосновать вложение","управлять ожиданиями","улучшить рабочий процесс"],"correctAnswer":"управлять ожиданиями","explanation":"«manage expectations» — «управлять ожиданиями»."},{"id":4,"question":"Выбери точное русское значение выражения «conduct market research».","options":["провести исследование рынка","прогнозировать спрос","укрепить лояльность клиентов","улучшить рабочий процесс"],"correctAnswer":"провести исследование рынка","explanation":"«conduct market research» — «провести исследование рынка»."},{"id":5,"question":"Какое выражение на британском английском соответствует «распределить ресурсы»?","options":["allocate resources","propose a compromise","address a bottleneck","improve the workflow"],"correctAnswer":"allocate resources","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":6,"question":"Выбери точное русское значение выражения «justify an investment».","options":["обосновать вложение","устранить узкое место","оценить коммерческий риск","управлять ожиданиями"],"correctAnswer":"обосновать вложение","explanation":"«justify an investment» — «обосновать вложение»."},{"id":7,"question":"Выбери точное русское значение выражения «address a bottleneck».","options":["прогнозировать спрос","устранить узкое место","управлять ожиданиями","улучшить рабочий процесс"],"correctAnswer":"устранить узкое место","explanation":"«address a bottleneck» — «устранить узкое место»."},{"id":8,"question":"Какое выражение на британском английском соответствует «улучшить рабочий процесс»?","options":["improve the workflow","allocate resources","review performance","justify an investment"],"correctAnswer":"improve the workflow","explanation":"«improve the workflow» — «улучшить рабочий процесс»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000111,'quizzes','{"id":760200000000111,"title":"C1 · Бизнес · Деловая переписка · Quiz 11","description":"C1: деловая переписка. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":43,"category":"Деловая переписка","track":"Бизнес","topic":"Деловая переписка","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «substantiate a recommendation».","options":["обосновать рекомендацию","определить измеримые результаты","выявить системные неэффективности","оценить долгосрочную жизнеспособность"],"correctAnswer":"обосновать рекомендацию","explanation":"«substantiate a recommendation» — «обосновать рекомендацию»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оценить долгосрочную жизнеспособность»?","options":["interpret financial indicators","assess long-term viability","identify structural inefficiencies","evaluate a trade-off"],"correctAnswer":"assess long-term viability","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":3,"question":"Выбери точное русское значение выражения «establish measurable outcomes».","options":["снизить операционный риск","оценить компромисс между целями","определить измеримые результаты","пересмотреть план внедрения"],"correctAnswer":"определить измеримые результаты","explanation":"«establish measurable outcomes» — «определить измеримые результаты»."},{"id":4,"question":"Выбери точное русское значение выражения «manage stakeholder expectations».","options":["обосновать рекомендацию","договориться о приемлемом решении","управлять ожиданиями заинтересованных сторон","снизить операционный риск"],"correctAnswer":"управлять ожиданиями заинтересованных сторон","explanation":"«manage stakeholder expectations» — «управлять ожиданиями заинтересованных сторон»."},{"id"