INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000114,'quizzes','{"id":760200000000114,"title":"A2 · Бизнес · Планирование и встречи · Quiz 14","description":"A2: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «work schedule».","options":["рабочее расписание","попросить отзыв","показатели продаж","обслуживание клиентов"],"correctAnswer":"рабочее расписание","explanation":"«work schedule» — «рабочее расписание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «совершить платёж»?","options":["make a payment","send an email","join a meeting","work schedule"],"correctAnswer":"make a payment","explanation":"«make a payment» — «совершить платёж»."},{"id":3,"question":"Выбери точное русское значение выражения «monthly report».","options":["ежемесячный отчёт","совершить платёж","рабочее расписание","собеседование"],"correctAnswer":"ежемесячный отчёт","explanation":"«monthly report» — «ежемесячный отчёт»."},{"id":4,"question":"Выбери точное русское значение выражения «check the price».","options":["попросить отзыв","проверить цену","собеседование","ежемесячный отчёт"],"correctAnswer":"проверить цену","explanation":"«check the price» — «проверить цену»."},{"id":5,"question":"Какое выражение на британском английском соответствует «обслуживание клиентов»?","options":["monthly report","join a meeting","customer service","work schedule"],"correctAnswer":"customer service","explanation":"«customer service» — «обслуживание клиентов»."},{"id":6,"question":"Выбери точное русское значение выражения «place an order».","options":["сделать заказ","ежемесячный отчёт","показатели продаж","присоединиться к встрече"],"correctAnswe