INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000115,'quizzes','{"id":760200000000115,"title":"B1 · Бизнес · Планирование и встречи · Quiz 15","description":"B1: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «increase efficiency».","options":["делегировать задачу","согласовать срок","рассмотреть жалобу","повысить эффективность"],"correctAnswer":"повысить эффективность","explanation":"«increase efficiency» — «повысить эффективность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «запросить уточнение»?","options":["follow up by email","request clarification","agree on a deadline","increase efficiency"],"correctAnswer":"request clarification","explanation":"«request clarification» — «запросить уточнение»."},{"id":3,"question":"Выбери точное русское значение выражения «delegate a task».","options":["запросить уточнение","рассмотреть жалобу","делегировать задачу","учесть расходы"],"correctAnswer":"делегировать задачу","explanation":"«delegate a task» — «делегировать задачу»."},{"id":4,"question":"Выбери точное русское значение выражения «handle a complaint».","options":["повысить эффективность","запросить уточнение","обсудить предложение","рассмотреть жалобу"],"correctAnswer":"рассмотреть жалобу","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":5,"question":"Какое выражение на британском английском соответствует «организовать семинар»?","options":["discuss a proposal","handle a complaint","organise a workshop","increase efficiency"],"correctAnswer":"organise a workshop","explanation":"«organise a workshop» — «организовать семинар»."},{"id":6,"question":"Выбери точное русское значение выражения «consider the costs».","options":["запросить уточнение","учесть расходы","пересмотреть бюджет","повысить эффективность"],"correctAnswer":"учесть расходы","explanation":"«consider the costs» — «учесть расходы»."},{"id":7,"question":"Выбери точное русское значение выражения «follow up by email».","options":["запросить уточнение","уточнить по электронной почте","рассмотреть жалобу","повысить эффективность"],"correctAnswer":"уточнить по электронной почте","explanation":"«follow up by email» — «уточнить по электронной почте»."},{"id":8,"question":"Какое выражение на британском английском соответствует «подготовить счёт»?","options":["prepare an invoice","request clarification","delegate a task","consider the costs"],"correctAnswer":"prepare an invoice","explanation":"«prepare an invoice» — «подготовить счёт»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000116,'quizzes','{"id":760200000000116,"title":"B2 · Бизнес · Планирование и встречи · Quiz 16","description":"B2: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":38,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «address a bottleneck».","options":["устранить узкое место","провести исследование рынка","улучшить рабочий процесс","распределить ресурсы"],"correctAnswer":"устранить узкое место","explanation":"«address a bottleneck» — «устранить узкое место»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прогнозировать спрос»?","options":["forecast demand","negotiate terms","assess commercial risk","review performance"],"correctAnswer":"forecast demand","explanation":"«forecast demand» — «прогнозировать спрос»."},{"id":3,"question":"Выбери точное русское значение выражения «negotiate terms».","options":["согласовать условия","прогнозировать спрос","обосновать вложение","предложить компромисс"],"correctAnswer":"согласовать условия","explanation":"«negotiate terms» — «согласовать условия»."},{"id":4,"question":"Выбери точное русское значение выражения «conduct market research».","options":["оценить результаты работы","провести исследование рынка","обосновать вложение","улучшить рабочий процесс"],"correctAnswer":"провести исследование рынка","explanation":"«conduct market research» — «провести исследование рынка»."},{"id":5,"question":"Какое выражение на британском английском соответствует «управлять ожиданиями»?","options":["address a bottleneck","review performance","manage expectations","improve the workflow"],"correctAnswer":"manage expectations","explanation":"«manage expectations» — «управлять ожиданиями»."},{"id":6,"question":"Выбери точное русское значение выражения «strengthen customer loyalty».","options":["распределить ресурсы","прогнозировать спрос","улучшить рабочий процесс","укрепить лояльность клиентов"],"correctAnswer":"укрепить лояльность клиентов","explanation":"«strengthen customer loyalty» — «укрепить лояльность клиентов»."},{"id":7,"question":"Выбери точное русское значение выражения «allocate resources».","options":["управлять ожиданиями","укрепить лояльность клиентов","обосновать вложение","распределить ресурсы"],"correctAnswer":"распределить ресурсы","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":8,"question":"Какое выражение на британском английском соответствует «улучшить рабочий процесс»?","options":["improve the workflow","propose a compromise","assess commercial risk","strengthen customer loyalty"],"correctAnswer":"improve the workflow","explanation":"«improve the workflow» — «улучшить рабочий процесс»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000117,'quizzes','{"id":760200000000117,"title":"C1 · Бизнес · Планирование и встречи · Quiz 17","description":"C1: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «establish measurable outcomes».","options":["определить измеримые результаты","снизить операционный риск","управлять ожиданиями заинтересованных сторон","согласовать стратегические цели"],"correctAnswer":"определить измеримые результаты","explanation":"«establish measurable outcomes» — «определить измеримые результаты»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выявить системные неэффективности»?","options":["mitigate operational risk","revise the implementation plan","establish measurable outcomes","identify structural inefficiencies"],"correctAnswer":"identify structural inefficiencies","explanation":"«identify structural inefficiencies» — «выявить системные неэффективности»."},{"id":3,"question":"Выбери точное русское значение выражения «revise the implementation plan».","options":["договориться о приемлемом решении","пересмотреть план внедрения","обосновать рекомендацию","определить измеримые результаты"],"correctAnswer":"пересмотреть план внедрения","explanation":"«revise the implementation plan» — «пересмотреть план внедрения»."},{"id":4,"question":"Выбери точное русское значение выражения «interpret financial indicators».","options":["пересмотреть план внедрения","обосновать рекомендацию","управлять ожиданиями заинтересованных сторон","интерпретировать финансовые показатели"],"correctAnswer":"интерпретировать финансовые показатели","explanation":"«interpret financial indicators» — «интерпретировать финансовые показатели»."},{"id":5,"question":"Какое выражение на британском английском соответствует «договориться о приемлемом решении»?","options":["interpret financial indicators","revise the implementation plan","mitigate operational risk","negotiate a workable settlement"],"correctAnswer":"negotiate a workable settlement","explanation":"«negotiate a workable settlement» — «договориться о приемлемом решении»."},{"id":6,"question":"Выбери точное русское значение выражения «substantiate a recommendation».","options":["обосновать рекомендацию","согласовать стратегические цели","выявить системные неэффективности","пересмотреть план внедрения"],"correctAnswer":"обосновать рекомендацию","explanation":"«substantiate a recommendation» — «обосновать рекомендацию»."},{"id":7,"question":"Выбери точное русское значение выражения «maintain professional discretion».","options":["обосновать рекомендацию","соблюдать профессиональную осмотрительность","согласовать стратегические цели","выявить системные неэффективности"],"correctAnswer":"соблюдать профессиональную осмотрительность","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «снизить операционный риск»?","options":["align strategic objectives","identify structural inefficiencies","interpret financial indicators","mitigate operational risk"],"correctAnswer":"mitigate operational risk","explanation":"«mitigate operational risk» — «снизить операционный риск»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
