INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000120,'quizzes','{"id":760200000000120,"title":"A2 · Бизнес · Деловые решения · Quiz 20","description":"A2: деловые решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Деловые решения","track":"Бизнес","topic":"Деловые решения","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «customer service».","options":["уложиться в срок","проверить цену","обслуживание клиентов","отправить электронное письмо"],"correctAnswer":"обслуживание клиентов","explanation":"«customer service» — «обслуживание клиентов»."},{"id":2,"question":"Какое выражение на британском английском соответствует «собеседование»?","options":["check the price","make a payment","job interview","join a meeting"],"correctAnswer":"job interview","explanation":"«job interview» — «собеседование»."},{"id":3,"question":"Выбери точное русское значение выражения «monthly report».","options":["ежемесячный отчёт","попросить отзыв","отправить электронное письмо","рабочее расписание"],"correctAnswer":"ежемесячный отчёт","explanation":"«monthly report» — «ежемесячный отчёт»."},{"id":4,"question":"Выбери точное русское значение выражения «join a meeting».","options":["отправить электронное письмо","собеседование","обслуживание клиентов","присоединиться к встрече"],"correctAnswer":"присоединиться к встрече","explanation":"«join a meeting» — «присоединиться к встрече»."},{"id":5,"question":"Какое выражение на британском английском соответствует «отправить электронное письмо»?","options":["sales figures","send an email","make a payment","ask for feedback"],"correctAnswer":"send an email","explanation":"«send an email» — «отправить электронное письмо»."},{"id":6,"question":"Выбери точное русское значение выражения «make a payment».","options":["уложиться в срок","ежемесячный отчёт","совершить платёж","отправить электронное письмо"],"correctAnswer":"совершить платёж","explanation":"«make a payment» — «совершить платёж»."},{"id":7,"question":"Выбери точное русское значение выражения «meet a deadline».","options":["уложиться в срок","попросить отзыв","показатели продаж","проверить цену"],"correctAnswer":"уложиться в срок","explanation":"«meet a deadline» — «уложиться в срок»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сделать заказ»?","options":["check the price","place an order","sales figures","send an email"],"correctAnswer":"place an order","explanation":"«place an order» — «сделать заказ»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000121,'quizzes','{"id":760200000000121,"title":"B1 · Бизнес · Деловые решения · Quiz 21","description":"B1: деловые решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":33,"category":"Деловые решения","track":"Бизнес","topic":"Деловые решения","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «consider the costs».","options":["учесть расходы","рассмотреть жалобу","запросить уточнение","организовать семинар"],"correctAnswer":"учесть расходы","explanation":"«consider the costs» — «учесть расходы»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обсудить предложение»?","options":["set priorities","discuss a proposal","increase efficiency","request clarification"],"correctAnswer":"discuss a proposal","explanation":"«discuss a proposal» — «обсудить предложение»."},{"id":3,"question":"Выбери точное русское значение выражения «agree on a deadline».","options":["согласовать срок","обсудить предложение","повысить эффективность","запросить уточнение"],"correctAnswer":"согласовать срок","explanation":"«agree on a deadline» — «согласовать срок»."},{"id":4,"question":"Выбери точное русское значение выражения «review the budget».","options":["уточнить по электронной почте","обсудить предложение","учесть расходы","пересмотреть бюджет"],"correctAnswer":"пересмотреть бюджет","explanation":"«review the budget» — «пересмотреть бюджет»."},{"id":5,"question":"Какое выражение на британском английском соответствует «рассмотреть жалобу»?","options":["handle a complaint","prepare an invoice","set priorities","delegate a task"],"correctAnswer":"handle a complaint","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":6,"question":"Выбери точное русское значение выражения «request clarification».","options":["рассмотреть жалобу","запросить уточнение","делегировать задачу","организовать семинар"],"correctAnswer":"запросить уточнение","explanation":"«request clarification» — «запросить уточнение»."},{"id":7,"question":"Выбери точное русское значение выражения «organise a workshop».","options":["делегировать задачу","организовать семинар","уточнить по электронной почте","расставить приоритеты"],"correctAnswer":"организовать семинар","explanation":"«organise a workshop» — «организовать семинар»."},{"id":8,"question":"Какое выражение на британском английском соответствует «подготовить счёт»?","options":["prepare an invoice","review the budget","follow up by email","set priorities"],"correctAnswer":"prepare an invoice","explanation":"«prepare an invoice» — «подготовить счёт»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000122,'quizzes','{"id":760200000000122,"title":"B2 · Бизнес · Деловые решения · Quiz 22","description":"B2: деловые решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Деловые решения","track":"Бизнес","topic":"Деловые решения","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «address a bottleneck».","options":["устранить узкое место","улучшить рабочий процесс","распределить ресурсы","оценить коммерческий риск"],"correctAnswer":"устранить узкое место","explanation":"«address a bottleneck» — «устранить узкое место»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прогнозировать спрос»?","options":["conduct market research","forecast demand","review performance","justify an investment"],"correctAnswer":"forecast demand","explanation":"«forecast demand» — «прогнозировать спрос»."},{"id":3,"question":"Выбери точное русское значение выражения «manage expectations».","options":["улучшить рабочий процесс","управлять ожиданиями","провести исследование рынка","предложить компромисс"],"correctAnswer":"управлять ожиданиями","explanation":"«manage expectations» — «управлять ожиданиями»."},{"id":4,"question":"Выбери точное русское значение выражения «negotiate terms».","options":["согласовать условия","предложить компромисс","провести исследование рынка","распределить ресурсы"],"correctAnswer":"согласовать условия","explanation":"«negotiate terms» — «согласовать условия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить компромисс»?","options":["negotiate terms","propose a compromise","manage expectations","forecast demand"],"correctAnswer":"propose a compromise","explanation":"«propose a compromise» — «предложить компромисс»."},{"id":6,"question":"Выбери точное русское значение выражения «improve the workflow».","options":["управлять ожиданиями","оценить результаты работы","устранить узкое место","улучшить рабочий процесс"],"correctAnswer":"улучшить рабочий процесс","explanation":"«improve the workflow» — «улучшить рабочий процесс»."},{"id":7,"question":"Выбери точное русское значение выражения «allocate resources».","options":["управлять ожиданиями","распределить ресурсы","оценить коммерческий риск","предложить компромисс"],"correctAnswer":"распределить ресурсы","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":8,"question":"Какое выражение на британском английском соответствует «обосновать вложение»?","options":["justify an investment","assess commercial risk","forecast demand","negotiate terms"],"correctAnswer":"justify an investment","explanation":"«justify an investment» — «обосновать вложение»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000123,'quizzes','{"id":760200000000123,"title":"C1 · Бизнес · Деловые решения · Quiz 23","description":"C1: деловые решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Деловые решения","track":"Бизнес","topic":"Деловые решения","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «negotiate a workable settlement».","options":["снизить операционный риск","обосновать рекомендацию","договориться о приемлемом решении","определить измеримые результаты"],"correctAnswer":"договориться о приемлемом решении","explanation":"«negotiate a workable settlement» — «договориться о приемлемом решении»."},{"id":2,"question":"Какое выражение на британском английском соответствует «соблюдать профессиональную осмотрительность»?","options":["mitigate operational risk","maintain professional discretion","align strategic objectives","negotiate a workable settlement"],"correctAnswer":"maintain professional discretion","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":3,"question":"Выбери точное русское значение выражения «revise the implementation plan».","options":["согласовать стратегические цели","оценить компромисс между целями","пересмотреть план внедрения","соблюдать профессиональную осмотрительность"],"correctAnswer":"пересмотреть план внедрения","explanation":"«revise the implementation plan» — «пересмотреть план внедрения»."},{"id":4,"question":"Выбери точное русское значение выражения «identify structural inefficiencies».","options":["оценить компромисс между целями","выявить системные неэффективности","согласовать стратегические цели","снизить операционный риск"],"correctAnswer":"выявить системные неэффективности","explanation":"«identify structural inefficiencies» — «выявить системные неэффективности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «управлять ожиданиями заинтересованных сторон»?","options":["establish measurable outcomes","identify structural inefficiencies","manage stakeholder expectations","interpret financial indicators"],"correctAnswer":"manage stakeholder expectations","explanation":"«manage stakeholder expectations» — «управлять ожиданиями заинтересованных сторон»."},{"id":6,"question":"Выбери точное русское значение выражения «mitigate operational risk».","options":["оценить компромисс между целями","пересмотреть план внедрения","снизить операционный риск","обосновать рекомендацию"],"correctAnswer":"снизить операционный риск","explanation":"«mitigate operational risk» — «снизить операционный риск»."},{"id":7,"question":"Выбери точное русское значение выражения «assess long-term viability».","options":["пересмотреть план внедрения","оценить долгосрочную жизнеспособность","соблюдать профессиональную осмотрительность","определить измеримые результаты"],"correctAnswer":"оценить долгосрочную жизнеспособность","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «интерпретировать финансовые показатели»?","options":["interpret financial indicators","substantiate a recommendation","mitigate operational risk","negotiate a workable settlement"],"correctAnswer":"interpret financial indicators","explanation":"«interpret financial indicators» — «интерпретировать финансовые показатели»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000124,'quizzes','{"id":760200000000124,"title":"C2 · Бизнес · Деловые решения · Quiz 24","description":"C2: деловые решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Деловые решения","track":"Бизнес","topic":"Деловые решения","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «quantify opportunity costs».","options":["оценить механизмы корпоративного управления","сформулировать последовательную стратегию","количественно оценить альтернативные издержки","оспорить чрезмерно оптимистичный прогноз"],"correctAnswer":"количественно оценить альтернативные издержки","explanation":"«quantify opportunity costs» — «количественно оценить альтернативные издержки»."},{"id":2,"question":"Какое выражение на британском английском соответствует «предвидеть регуляторные последствия»?","options":["anticipate regulatory implications","reconcile divergent incentives","quantify opportunity costs","formulate a defensible valuation"],"correctAnswer":"anticipate regulatory implications","explanation":"«anticipate regulatory implications» — «предвидеть регуляторные последствия»."},{"id":3,"question":"Выбери точное русское значение выражения «evaluate governance safeguards».","options":["оспорить чрезмерно оптимистичный прогноз","оценить механизмы корпоративного управления","устранить системную подверженность риску","предвидеть регуляторные последствия"],"correctAnswer":"оценить механизмы корпоративного управления","explanation":"«evaluate governance safeguards» — «оценить механизмы корпоративного управления»."},{"id":4,"question":"Выбери точное русское значение выражения «formulate a defensible valuation».","options":["обосновать изменение стратегии","оценить механизмы корпоративного управления","подготовить обоснованную оценку стоимости","оспорить чрезмерно оптимистичный прогноз"],"correctAnswer":"подготовить обоснованную оценку стоимости","explanation":"«formulate a defensible valuation» — «подготовить обоснованную оценку стоимости»."},{"id":5,"question":"Какое выражение на британском английском соответствует «тщательно проверить исходные предпосылки»?","options":["formulate a defensible valuation","challenge an optimistic forecast","evaluate governance safeguards","scrutinise the underlying assumptions"],"correctAnswer":"scrutinise the underlying assumptions","explanation":"«scrutinise the underlying assumptions» — «тщательно проверить исходные предпосылки»."},{"id":6,"question":"Выбери точное русское значение выражения «synthesise conflicting evidence».","options":["предвидеть регуляторные последствия","устранить системную подверженность риску","свести воедино противоречивые данные","обосновать изменение стратегии"],"correctAnswer":"свести воедино противоречивые данные","explanation":"«synthesise conflicting evidence» — «свести воедино противоречивые данные»."},{"id":7,"question":"Выбери точное русское значение выражения «challenge an optimistic forecast».","options":["оспорить чрезмерно оптимистичный прогноз","обосновать изменение стратегии","устранить системную подверженность риску","согласовать расходящиеся стимулы"],"correctAnswer":"оспорить чрезмерно оптимистичный прогноз","explanation":"«challenge an optimistic forecast» — «оспорить чрезмерно оптимистичный прогноз»."},{"id":8,"question":"Какое выражение на британском английском соответствует «устранить системную подверженность риску»?","options":["anticipate regulatory implications","address systemic exposure","articulate a coherent strategy","reconcile divergent incentives"],"correctAnswer":"address systemic exposure","explanation":"«address systemic exposure» — «устранить системную подверженность риску»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
