INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000126,'quizzes','{"id":760200000000126,"title":"A2 · Бизнес · Проекты и результаты · Quiz 26","description":"A2: проекты и результаты. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":28,"category":"Проекты и результаты","track":"Бизнес","topic":"Проекты и результаты","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «work schedule».","options":["рабочее расписание","совершить платёж","отправить электронное письмо","уложиться в срок"],"correctAnswer":"рабочее расписание","explanation":"«work schedule» — «рабочее расписание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «попросить отзыв»?","options":["ask for feedback","work schedule","customer service","monthly report"],"correctAnswer":"ask for feedback","explanation":"«ask for feedback» — «попросить отзыв»."},{"id":3,"question":"Выбери точное русское значение выражения «send an email».","options":["ежемесячный отчёт","показатели продаж","отправить электронное письмо","попросить отзыв"],"correctAnswer":"отправить электронное письмо","explanation":"«send an email» — «отправить электронное письмо»."},{"id":4,"question":"Выбери точное русское значение выражения «join a meeting».","options":["присоединиться к встрече","ежемесячный отчёт","собеседование","рабочее расписание"],"correctAnswer":"присоединиться к встрече","explanation":"«join a meeting» — «присоединиться к встрече»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сделать заказ»?","options":["place an order","make a payment","meet a deadline","ask for feedback"],"correctAnswer":"place an order","explanation":"«place an order» — «сделать заказ»."},{"id":6,"question":"Выбери точное русское значение выражения «monthly report».","options":["ежемесячный отчёт","показатели продаж","прис