INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000127,'quizzes','{"id":760200000000127,"title":"B1 · Бизнес · Проекты и результаты · Quiz 27","description":"B1: проекты и результаты. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Проекты и результаты","track":"Бизнес","topic":"Проекты и результаты","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «set priorities».","options":["организовать семинар","расставить приоритеты","обсудить предложение","пересмотреть бюджет"],"correctAnswer":"расставить приоритеты","explanation":"«set priorities» — «расставить приоритеты»."},{"id":2,"question":"Какое выражение на британском английском соответствует «рассмотреть жалобу»?","options":["agree on a deadline","prepare an invoice","request clarification","handle a complaint"],"correctAnswer":"handle a complaint","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":3,"question":"Выбери точное русское значение выражения «delegate a task».","options":["делегировать задачу","запросить уточнение","согласовать срок","обсудить предложение"],"correctAnswer":"делегировать задачу","explanation":"«delegate a task» — «делегировать задачу»."},{"id":4,"question":"Выбери точное русское значение выражения «discuss a proposal».","options":["уточнить по электронной почте","рассмотреть жалобу","обсудить предложение","повысить эффективность"],"correctAnswer":"обсудить предложение","explanation":"«discuss a proposal» — «обсудить предложение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «повысить эффективность»?","options":["agree on a deadline","increase efficiency","request clarification","consider the costs"],"correctAnswer":"increase efficiency","explanation":"«increase efficiency» — «повысить эффективность»."},{"id":6,"question":"Выбери точное русское значение вы