INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000128,'quizzes','{"id":760200000000128,"title":"B2 · Бизнес · Проекты и результаты · Quiz 28","description":"B2: проекты и результаты. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Проекты и результаты","track":"Бизнес","topic":"Проекты и результаты","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «strengthen customer loyalty».","options":["укрепить лояльность клиентов","обосновать вложение","согласовать условия","оценить коммерческий риск"],"correctAnswer":"укрепить лояльность клиентов","explanation":"«strengthen customer loyalty» — «укрепить лояльность клиентов»."},{"id":2,"question":"Какое выражение на британском английском соответствует «распределить ресурсы»?","options":["review performance","justify an investment","allocate resources","conduct market research"],"correctAnswer":"allocate resources","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":3,"question":"Выбери точное русское значение выражения «assess commercial risk».","options":["обосновать вложение","прогнозировать спрос","устранить узкое место","оценить коммерческий риск"],"correctAnswer":"оценить коммерческий риск","explanation":"«assess commercial risk» — «оценить коммерческий риск»."},{"id":4,"question":"Выбери точное русское значение выражения «negotiate terms».","options":["улучшить рабочий процесс","оценить коммерческий риск","согласовать условия","распределить ресурсы"],"correctAnswer":"согласовать условия","explanation":"«negotiate terms» — «согласовать условия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить компромисс»?","options":["allocate resources","negotiate terms","propose a compromise","address a bottleneck"],"correctAnswer":"propose a compromise","explanation":"«propose a compromise» — «предложить компромисс»."},{"id":6,"question":"Выбери точное русское значение выражения «address a bottleneck».","options":["провести исследование рынка","оценить результаты работы","оценить коммерческий риск","устранить узкое место"],"correctAnswer":"устранить узкое место","explanation":"«address a bottleneck» — «устранить узкое место»."},{"id":7,"question":"Выбери точное русское значение выражения «conduct market research».","options":["провести исследование рынка","оценить коммерческий риск","предложить компромисс","обосновать вложение"],"correctAnswer":"провести исследование рынка","explanation":"«conduct market research» — «провести исследование рынка»."},{"id":8,"question":"Какое выражение на британском английском соответствует «управлять ожиданиями»?","options":["forecast demand","manage expectations","strengthen customer loyalty","address a bottleneck"],"correctAnswer":"manage expectations","explanation":"«manage expectations» — «управлять ожиданиями»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000129,'quizzes','{"id":760200000000129,"title":"C1 · Бизнес · Проекты и результаты · Quiz 29","description":"C1: проекты и результаты. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Проекты и результаты","track":"Бизнес","topic":"Проекты и результаты","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «mitigate operational risk».","options":["снизить операционный риск","управлять ожиданиями заинтересованных сторон","договориться о приемлемом решении","пересмотреть план внедрения"],"correctAnswer":"снизить операционный риск","explanation":"«mitigate operational risk» — «снизить операционный риск»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оценить долгосрочную жизнеспособность»?","options":["establish measurable outcomes","assess long-term viability","negotiate a workable settlement","align strategic objectives"],"correctAnswer":"assess long-term viability","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":3,"question":"Выбери точное русское значение выражения «revise the implementation plan».","options":["обосновать рекомендацию","пересмотреть план внедрения","оценить компромисс между целями","согласовать стратегические цели"],"correctAnswer":"пересмотреть план внедрения","explanation":"«revise the implementation plan» — «пересмотреть план внедрения»."},{"id":4,"question":"Выбери точное русское значение выражения «negotiate a workable settlement».","options":["снизить операционный риск","выявить системные неэффективности","договориться о приемлемом решении","интерпретировать финансовые показатели"],"correctAnswer":"договориться о приемлемом решении","explanation":"«negotiate a workable settlement» — «договориться о приемлемом решении»."},{"id":5,"questio