INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000132,'quizzes','{"id":760200000000132,"title":"A2 · Бизнес · Работа и команда · Quiz 32","description":"A2: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «sales figures».","options":["показатели продаж","уложиться в срок","отправить электронное письмо","присоединиться к встрече"],"correctAnswer":"показатели продаж","explanation":"«sales figures» — «показатели продаж»."},{"id":2,"question":"Какое выражение на британском английском соответствует «проверить цену»?","options":["check the price","place an order","join a meeting","work schedule"],"correctAnswer":"check the price","explanation":"«check the price» — «проверить цену»."},{"id":3,"question":"Выбери точное русское значение выражения «monthly report».","options":["показатели продаж","сделать заказ","ежемесячный отчёт","обслуживание клиентов"],"correctAnswer":"ежемесячный отчёт","explanation":"«monthly report» — «ежемесячный отчёт»."},{"id":4,"question":"Выбери точное русское значение выражения «customer service».","options":["присоединиться к встрече","попросить отзыв","проверить цену","обслуживание клиентов"],"correctAnswer":"обслуживание клиентов","explanation":"«customer service» — «обслуживание клиентов»."},{"id":5,"question":"Какое выражение на британском английском соответствует «присоединиться к встрече»?","options":["place an order","job interview","join a meeting","monthly report"],"correctAnswer":"join a meeting","explanation":"«join a meeting» — «присоединиться к встрече»."},{"id":6,"question":"Выбери точное русское значение выражения «send an email».","options":["собеседование","проверить цену","рабочее расписание","отправить электронно