INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000133,'quizzes','{"id":760200000000133,"title":"B1 · Бизнес · Работа и команда · Quiz 33","description":"B1: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «delegate a task».","options":["учесть расходы","запросить уточнение","согласовать срок","делегировать задачу"],"correctAnswer":"делегировать задачу","explanation":"«delegate a task» — «делегировать задачу»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обсудить предложение»?","options":["organise a workshop","delegate a task","discuss a proposal","follow up by email"],"correctAnswer":"discuss a proposal","explanation":"«discuss a proposal» — «обсудить предложение»."},{"id":3,"question":"Выбери точное русское значение выражения «agree on a deadline».","options":["подготовить счёт","согласовать срок","запросить уточнение","расставить приоритеты"],"correctAnswer":"согласовать срок","explanation":"«agree on a deadline» — «согласовать срок»."},{"id":4,"question":"Выбери точное русское значение выражения «request clarification».","options":["запросить уточнение","учесть расходы","пересмотреть бюджет","рассмотреть жалобу"],"correctAnswer":"запросить уточнение","explanation":"«request clarification» — «запросить уточнение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «рассмотреть жалобу»?","options":["consider the costs","handle a complaint","request clarification","agree on a deadline"],"correctAnswer":"handle a complaint","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":6,"question":"Выбери точное русское значение выражения «organise a workshop».","options":["расставить приоритеты","организовать семинар","пересмотреть бюджет","рассмотреть жалобу"],"correctAnswer":"организовать семинар","explanation":"«organise a workshop» — «организовать семинар»."},{"id":7,"question":"Выбери точное русское значение выражения «increase efficiency».","options":["повысить эффективность","организовать семинар","подготовить счёт","делегировать задачу"],"correctAnswer":"повысить эффективность","explanation":"«increase efficiency» — «повысить эффективность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «подготовить счёт»?","options":["prepare an invoice","increase efficiency","request clarification","handle a complaint"],"correctAnswer":"prepare an invoice","explanation":"«prepare an invoice» — «подготовить счёт»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000134,'quizzes','{"id":760200000000134,"title":"B2 · Бизнес · Работа и команда · Quiz 34","description":"B2: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «improve the workflow».","options":["улучшить рабочий процесс","управлять ожиданиями","устранить узкое место","прогнозировать спрос"],"correctAnswer":"улучшить рабочий процесс","explanation":"«improve the workflow» — «улучшить рабочий процесс»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прогнозировать спрос»?","options":["address a bottleneck","negotiate terms","forecast demand","justify an investment"],"correctAnswer":"forecast demand","explanation":"«forecast demand» — «прогнозировать спрос»."},{"id":3,"question":"Выбери точное русское значение выражения «justify an investment».","options":["оценить результаты работы","прогнозировать спрос","обосновать вложение","устранить узкое место"],"correctAnswer":"обосновать вложение","explanation":"«justify an investment» — «обосновать вложение»."},{"id":4,"question":"Выбери точное русское значение выражения «conduct market research».","options":["обосновать вложение","устранить узкое место","провести исследование рынка","улучшить рабочий процесс"],"correctAnswer":"провести исследование рынка","explanation":"«conduct market research» — «провести исследование рынка»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить компромисс»?","options":["negotiate terms","assess commercial risk","propose a compromise","strengthen customer loyalty"],"correctAnswer":"propose a compromise","explanation":"«propose a compromise» — «предложить компромисс»."},{"id":6,"question":"Выбери точное русское значение выражения «allocate resources».","options":["распределить ресурсы","провести исследование рынка","обосновать вложение","оценить результаты работы"],"correctAnswer":"распределить ресурсы","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":7,"question":"Выбери точное русское значение выражения «assess commercial risk».","options":["оценить результаты работы","согласовать условия","оценить коммерческий риск","прогнозировать спрос"],"correctAnswer":"оценить коммерческий риск","explanation":"«assess commercial risk» — «оценить коммерческий риск»."},{"id":8,"question":"Какое выражение на британском английском соответствует «согласовать условия»?","options":["negotiate terms","justify an investment","allocate resources","assess commercial risk"],"correctAnswer":"negotiate terms","explanation":"«negotiate terms» — «согласовать условия»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000135,'quizzes','{"id":760200000000135,"title":"C1 · Бизнес · Работа и команда · Quiz 35","description":"C1: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «maintain professional discretion».","options":["управлять ожиданиями заинтересованных сторон","выявить системные неэффективности","определить измеримые результаты","соблюдать профессиональную осмотрительность"],"correctAnswer":"соблюдать профессиональную осмотрительность","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «снизить операционный риск»?","options":["establish measurable outcomes","mitigate operational risk","substantiate a recommendation","assess long-term viability"],"correctAnswer":"mitigate operational risk","explanation":"«mitigate operational risk» — «снизить операционный риск»."},{"id":3,"question":"Выбери точное русское значение выражения «evaluate a trade-off».","options":["оценить компромисс между целями","обосновать рекомендацию","соблюдать профессиональную осмотрительность","договориться о приемлемом решении"],"correctAnswer":"оценить компромисс между целями","explanation":"«evaluate a trade-off» — «оценить компромисс между целями»."},{"id":4,"question":"Выбери точное русское значение выражения «establish measurable outcomes».","options":["определить измеримые результаты","выявить системные неэффективности","оценить компромисс между целями","согласовать стратегические цели"],"correctAnswer":"определить измеримые результаты","explanation":"«establish measurable outcomes» — «определить измеримые результаты»."},{"id":5,"question":"Какое выражение на британском английском соответствует «согласовать стратегические цели»?","options":["maintain professional discretion","interpret financial indicators","evaluate a trade-off","align strategic objectives"],"correctAnswer":"align strategic objectives","explanation":"«align strategic objectives» — «согласовать стратегические цели»."},{"id":6,"question":"Выбери точное русское значение выражения «interpret financial indicators».","options":["договориться о приемлемом решении","интерпретировать финансовые показатели","согласовать стратегические цели","оценить компромисс между целями"],"correctAnswer":"интерпретировать финансовые показатели","explanation":"«interpret financial indicators» — «интерпретировать финансовые показатели»."},{"id":7,"question":"Выбери точное русское значение выражения «assess long-term viability».","options":["определить измеримые результаты","оценить долгосрочную жизнеспособность","согласовать стратегические цели","оценить компромисс между целями"],"correctAnswer":"оценить долгосрочную жизнеспособность","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «пересмотреть план внедрения»?","options":["revise the implementation plan","identify structural inefficiencies","substantiate a recommendation","maintain professional discretion"],"correctAnswer":"revise the implementation plan","explanation":"«revise the implementation plan» — «пересмотреть план внедрения»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000136,'quizzes','{"id":760200000000136,"title":"C2 · Бизнес · Работа и команда · Quiz 36","description":"C2: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":48,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «challenge an optimistic forecast».","options":["оспорить чрезмерно оптимистичный прогноз","сформулировать последовательную стратегию","предвидеть регуляторные последствия","тщательно проверить исходные предпосылки"],"correctAnswer":"оспорить чрезмерно оптимистичный прогноз","explanation":"«challenge an optimistic forecast» — «оспорить чрезмерно оптимистичный прогноз»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать последовательную стратегию»?","options":["address systemic exposure","synthesise conflicting evidence","formulate a defensible valuation","articulate a coherent strategy"],"correctAnswer":"articulate a coherent strategy","explanation":"«articulate a coherent strategy» — «сформулировать последовательную стратегию»."},{"id":3,"question":"Выбери точное русское значение выражения «anticipate regulatory implications».","options":["оценить механизмы корпоративного управления","сформулировать последовательную стратегию","предвидеть регуляторные последствия","тщательно проверить исходные предпосылки"],"correctAnswer":"предвидеть регуляторные последствия","explanation":"«anticipate regulatory implications» — «предвидеть регуляторные последствия»."},{"id":4,"question":"Выбери точное русское значение выражения «address systemic exposure».","options":["устранить системную подверженность риску","обосновать изменение стратегии","свести воедино противоречивые данные","подготовить обоснованную оценку стоимости"],"correctAnswer":"устранить системную подверженность риску","explanation":"«address systemic exposure» — «устранить системную подверженность риску»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сбалансировать ликвидность и рост»?","options":["synthesise conflicting evidence","challenge an optimistic forecast","balance liquidity against growth","quantify opportunity costs"],"correctAnswer":"balance liquidity against growth","explanation":"«balance liquidity against growth» — «сбалансировать ликвидность и рост»."},{"id":6,"question":"Выбери точное русское значение выражения «formulate a defensible valuation».","options":["подготовить обоснованную оценку стоимости","тщательно проверить исходные предпосылки","сформулировать последовательную стратегию","обосновать изменение стратегии"],"correctAnswer":"подготовить обоснованную оценку стоимости","explanation":"«formulate a defensible valuation» — «подготовить обоснованную оценку стоимости»."},{"id":7,"question":"Выбери точное русское значение выражения «justify a strategic pivot».","options":["обосновать изменение стратегии","оценить механизмы корпоративного управления","согласовать расходящиеся стимулы","оспорить чрезмерно оптимистичный прогноз"],"correctAnswer":"обосновать изменение стратегии","explanation":"«justify a strategic pivot» — «обосновать изменение стратегии»."},{"id":8,"question":"Какое выражение на британском английском соответствует «свести воедино противоречивые данные»?","options":["scrutinise the underlying assumptions","anticipate regulatory implications","synthesise conflicting evidence","address systemic exposure"],"correctAnswer":"synthesise conflicting evidence","explanation":"«synthesise conflicting evidence» — «свести воедино противоречивые данные»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
