INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000144,'quizzes','{"id":760200000000144,"title":"A2 · Бизнес · Планирование и встречи · Quiz 44","description":"A2: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «work schedule».","options":["рабочее расписание","ежемесячный отчёт","присоединиться к встрече","отправить электронное письмо"],"correctAnswer":"рабочее расписание","explanation":"«work schedule» — «рабочее расписание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «совершить платёж»?","options":["ask for feedback","send an email","make a payment","customer service"],"correctAnswer":"make a payment","explanation":"«make a payment» — «совершить платёж»."},{"id":3,"question":"Выбери точное русское значение выражения «check the price».","options":["ежемесячный отчёт","рабочее расписание","проверить цену","собеседование"],"correctAnswer":"проверить цену","explanation":"«check the price» — «проверить цену»."},{"id":4,"question":"Выбери точное русское значение выражения «sales figures».","options":["уложиться в срок","показатели продаж","проверить цену","попросить отзыв"],"correctAnswer":"показатели продаж","explanation":"«sales figures» — «показатели продаж»."},{"id":5,"question":"Какое выражение на британском английском соответствует «попросить отзыв»?","options":["sales figures","meet a deadline","check the price","ask for feedback"],"correctAnswer":"ask for feedback","explanation":"«ask for feedback» — «попросить отзыв»."},{"id":6,"question":"Выбери точное русское значение выражения «customer service».","options":["присоединиться к встрече","совершить платёж","обслуживание клиентов","показатели продаж"],"correctAnswer":"обслуживание клиентов","explanation":"«customer service» — «обслуживание клиентов»."},{"id":7,"question":"Выбери точное русское значение выражения «send an email».","options":["сделать заказ","отправить электронное письмо","уложиться в срок","собеседование"],"correctAnswer":"отправить электронное письмо","explanation":"«send an email» — «отправить электронное письмо»."},{"id":8,"question":"Какое выражение на британском английском соответствует «собеседование»?","options":["sales figures","job interview","join a meeting","meet a deadline"],"correctAnswer":"job interview","explanation":"«job interview» — «собеседование»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000145,'quizzes','{"id":760200000000145,"title":"B1 · Бизнес · Планирование и встречи · Quiz 45","description":"B1: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «discuss a proposal».","options":["организовать семинар","согласовать срок","обсудить предложение","учесть расходы"],"correctAnswer":"обсудить предложение","explanation":"«discuss a proposal» — «обсудить предложение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «подготовить счёт»?","options":["request clarification","delegate a task","agree on a deadline","prepare an invoice"],"correctAnswer":"prepare an invoice","explanation":"«prepare an invoice» — «подготовить счёт»."},{"id":3,"question":"Выбери точное русское значение выражения «request clarification».","options":["повысить эффективность","запросить уточнение","согласовать срок","пересмотреть бюджет"],"correctAnswer":"запросить уточнение","explanation":"«request clarification» — «запросить уточнение»."},{"id":4,"question":"Выбери точное русское значение выражения «increase efficiency».","options":["повысить эффективность","рассмотреть жалобу","согласовать срок","пересмотреть бюджет"],"correctAnswer":"повысить эффективность","explanation":"«increase efficiency» — «повысить эффективность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «рассмотреть жалобу»?","options":["agree on a deadline","handle a complaint","set priorities","consider the costs"],"correctAnswer":"handle a complaint","explanation":"«handle a complaint» — «рассмотреть жалобу»."},{"id":6,"question":"Выбери точное русское значение выражения «review