INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000146,'quizzes','{"id":760200000000146,"title":"B2 · Бизнес · Планирование и встречи · Quiz 46","description":"B2: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":38,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «propose a compromise».","options":["провести исследование рынка","улучшить рабочий процесс","оценить результаты работы","предложить компромисс"],"correctAnswer":"предложить компромисс","explanation":"«propose a compromise» — «предложить компромисс»."},{"id":2,"question":"Какое выражение на британском английском соответствует «укрепить лояльность клиентов»?","options":["assess commercial risk","allocate resources","improve the workflow","strengthen customer loyalty"],"correctAnswer":"strengthen customer loyalty","explanation":"«strengthen customer loyalty» — «укрепить лояльность клиентов»."},{"id":3,"question":"Выбери точное русское значение выражения «address a bottleneck».","options":["провести исследование рынка","согласовать условия","распределить ресурсы","устранить узкое место"],"correctAnswer":"устранить узкое место","explanation":"«address a bottleneck» — «устранить узкое место»."},{"id":4,"question":"Выбери точное русское значение выражения «manage expectations».","options":["оценить коммерческий риск","управлять ожиданиями","обосновать вложение","предложить компромисс"],"correctAnswer":"управлять ожиданиями","explanation":"«manage expectations» — «управлять ожиданиями»."},{"id":5,"question":"Какое выражение на британском английском соответствует «обосновать вложение»?","options":["address a bottleneck","justify an investment","strengthen customer loyalty","manage expectations"],"correctAnswer":"justify an investment","explanation":"«justify an investment» — «обосновать вложение»."},{"id":6,"question":"Выбери точное русское значение выражения «negotiate terms».","options":["управлять ожиданиями","провести исследование рынка","предложить компромисс","согласовать условия"],"correctAnswer":"согласовать условия","explanation":"«negotiate terms» — «согласовать условия»."},{"id":7,"question":"Выбери точное русское значение выражения «allocate resources».","options":["распределить ресурсы","обосновать вложение","укрепить лояльность клиентов","провести исследование рынка"],"correctAnswer":"распределить ресурсы","explanation":"«allocate resources» — «распределить ресурсы»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оценить результаты работы»?","options":["forecast demand","negotiate terms","review performance","propose a compromise"],"correctAnswer":"review performance","explanation":"«review performance» — «оценить результаты работы»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000147,'quizzes','{"id":760200000000147,"title":"C1 · Бизнес · Планирование и встречи · Quiz 47","description":"C1: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «substantiate a recommendation».","options":["пересмотреть план внедрения","выявить системные неэффективности","интерпретировать финансовые показатели","обосновать рекомендацию"],"correctAnswer":"обосновать рекомендацию","explanation":"«substantiate a recommendation» — «обосновать рекомендацию»."},{"id":2,"question":"Какое выражение на британском английском соответствует «снизить операционный риск»?","options":["mitigate operational risk","negotiate a workable settlement","assess long-term viability","evaluate a trade-off"],"correctAnswer":"mitigate operational risk","explanation":"«mitigate operational risk» — «снизить операционный риск»."},{"id":3,"question":"Выбери точное русское значение выражения «negotiate a workable settlement».","options":["управлять ожиданиями заинтересованных сторон","договориться о приемлемом решении","выявить системные неэффективности","оценить долгосрочную жизнеспособность"],"correctAnswer":"договориться о приемлемом решении","explanation":"«negotiate a workable settlement» — «договориться о приемлемом решении»."},{"id":4,"question":"Выбери точное русское значение выражения «evaluate a trade-off».","options":["определить измеримые результаты","согласовать стратегические цели","интерпретировать финансовые показатели","оценить компромисс между целями"],"correctAnswer":"оценить компромисс между целями","explanation":"«evaluate a trade-off» — «оценить компромисс между целями»."},{"id":5,"question":"Какое выражение на британском английском соответствует «соблюдать профессиональную осмотрительность»?","options":["negotiate a workable settlement","maintain professional discretion","revise the implementation plan","manage stakeholder expectations"],"correctAnswer":"maintain professional discretion","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":6,"question":"Выбери точное русское значение выражения «interpret financial indicators».","options":["соблюдать профессиональную осмотрительность","выявить системные неэффективности","интерпретировать финансовые показатели","обосновать рекомендацию"],"correctAnswer":"интерпретировать финансовые показатели","explanation":"«interpret financial indicators» — «интерпретировать финансовые показатели»."},{"id":7,"question":"Выбери точное русское значение выражения «align strategic objectives».","options":["согласовать стратегические цели","определить измеримые результаты","пересмотреть план внедрения","соблюдать профессиональную осмотрительность"],"correctAnswer":"согласовать стратегические цели","explanation":"«align strategic objectives» — «согласовать стратегические цели»."},{"id":8,"question":"Какое выражение на британском английском соответствует «пересмотреть план внедрения»?","options":["manage stakeholder expectations","revise the implementation plan","align strategic objectives","mitigate operational risk"],"correctAnswer":"revise the implementation plan","explanation":"«revise the implementation plan» — «пересмотреть план внедрения»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000148,'quizzes','{"id":760200000000148,"title":"C2 · Бизнес · Планирование и встречи · Quiz 48","description":"C2: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «evaluate governance safeguards».","options":["подготовить обоснованную оценку стоимости","оценить механизмы корпоративного управления","оспорить чрезмерно оптимистичный прогноз","сбалансировать ликвидность и рост"],"correctAnswer":"оценить механизмы корпоративного управления","explanation":"«evaluate governance safeguards» — «оценить механизмы корпоративного управления»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать последовательную стратегию»?","options":["reconcile divergent incentives","justify a strategic pivot","address systemic exposure","articulate a coherent strategy"],"correctAnswer":"articulate a coherent strategy","explanation":"«articulate a coherent strategy» — «сформулировать последовательную стратегию»."},{"id":3,"question":"Выбери точное русское значение выражения «address systemic exposure».","options":["устранить системную подверженность риску","оспорить чрезмерно оптимистичный прогноз","предвидеть регуляторные последствия","сформулировать последовательную стратегию"],"correctAnswer":"устранить системную подверженность риску","explanation":"«address systemic exposure» — «устранить системную подверженность риску»."},{"id":4,"question":"Выбери точное русское значение выражения «synthesise conflicting evidence».","options":["предвидеть регуляторные последствия","свести воедино противоречивые данные","количественно оценить альтернативные издержки","устранить системную подверженность риску"],"correctAnswer":"свести воедино противоречивые данные","explanation":"«synthesise conflicting evidence» — «свести воедино противоречивые данные»."},{"id":5,"question":"Какое выражение на британском английском соответствует «количественно оценить альтернативные издержки»?","options":["quantify opportunity costs","articulate a coherent strategy","scrutinise the underlying assumptions","synthesise conflicting evidence"],"correctAnswer":"quantify opportunity costs","explanation":"«quantify opportunity costs» — «количественно оценить альтернативные издержки»."},{"id":6,"question":"Выбери точное русское значение выражения «balance liquidity against growth».","options":["оценить механизмы корпоративного управления","сбалансировать ликвидность и рост","тщательно проверить исходные предпосылки","оспорить чрезмерно оптимистичный прогноз"],"correctAnswer":"сбалансировать ликвидность и рост","explanation":"«balance liquidity against growth» — «сбалансировать ликвидность и рост»."},{"id":7,"question":"Выбери точное русское значение выражения «anticipate regulatory implications».","options":["согласовать расходящиеся стимулы","предвидеть регуляторные последствия","количественно оценить альтернативные издержки","оспорить чрезмерно оптимистичный прогноз"],"correctAnswer":"предвидеть регуляторные последствия","explanation":"«anticipate regulatory implications» — «предвидеть регуляторные последствия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить чрезмерно оптимистичный прогноз»?","options":["articulate a coherent strategy","evaluate governance safeguards","challenge an optimistic forecast","reconcile divergent incentives"],"correctAnswer":"challenge an optimistic forecast","explanation":"«challenge an optimistic forecast» — «оспорить чрезмерно оптимистичный прогноз»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
